import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    var a = scanner.nextLong()
    var c = scanner.nextLong()

    var b = 0L
    var i = 0
    val x = LongArray(105)
    val y = LongArray(105)

    while (a + c > 0) {
        i++
        x[i] = a % 3
        a /= 3
        y[i] = c % 3
        c /= 3
    }

    while (i > 0) {
        b = b * 3 + ((y[i] - x[i] + 3) % 3)
        i--
    }

    println(b)
}

